custom_css:
@import url('https://fonts.googleapis.com/css2?family=Gowun+Batang:wght@400;700&family=Nanum+Myeongjo:wght@400;700;800&family=Noto+Serif+KR:wght@400;600&family=IBM+Plex+Mono:wght@400;500&display=swap');

/* ==========================================================================
   원고지 · Wongoji — SillyTavern theme
   흰 종이, 먹, 그리고 청회색으로 인쇄된 원고지 칸.

   아래 :root 변수만 바꿔도 대부분의 인상을 조정할 수 있습니다.
   ========================================================================== */

:root {
    /* 종이와 먹 — 흑백 */
    --wg-desk: #ffffff;           /* 바탕 */
    --wg-paper: #ffffff;          /* 원고지 종이 */
    --wg-paper-user: #f3f5f7;     /* 유저 원고지 — 아주 옅은 청회색 */
    --wg-ink: #1c1e21;            /* 먹 */
    --wg-ink-body: #212327;       /* 본문 */
    --wg-ink-soft: #5b636c;       /* 옅은 먹 */
    --wg-ink-faint: #8d949b;      /* 연필 */

    /* 원고지 인쇄색 — 청회색 */
    --wg-print: #6d7f91;          /* 칸 테두리 */
    --wg-print-line: rgba(109, 127, 145, 0.55);
    --wg-print-faint: rgba(109, 127, 145, 0.20);
    --wg-wash: #e4e9ee;           /* 청회색 바탕 (인용, 머리띠) */

    /* 강조 */
    --wg-quote: #1c1e21;          /* “대사” — 먹 */
    --wg-em: #4d5d6e;             /* *지문·속마음* — 청회색 */

    /* 폴라로이드 사진 필터. 흑백으로 보고 싶다면 grayscale(1) */
    --wg-photo-filter: none;

    /* ── 폴라로이드 아래 글귀 ─────────────────────────────
       따옴표 안의 글자만 바꾸면 됩니다. 예) '春風秋雨', '그날의 기록'
       花樣年華 (화양연화) — 인생에서 가장 아름다운 한때
       雪泥鴻爪 (설니홍조) — 눈 위에 남은 기러기 발자국, 덧없는 삶의 흔적  */
    --wg-caption-char: '花樣年華';
    --wg-caption-user: '雪泥鴻爪';

    /* 띠 위 여백에 인쇄된 이름 (토큰 수가 뒤에 붙습니다) */
    --wg-paper-label: '原稿用紙';

    /* 서체 */
    --wg-serif: 'Gowun Batang', 'Nanum Myeongjo', 'Noto Serif KR', serif;
    --wg-title: 'Nanum Myeongjo', 'Noto Serif KR', 'Gowun Batang', serif;
    --wg-hanja: 'Noto Serif KR', 'Nanum Myeongjo', serif;   /* 한자가 있는 명조 */
    --wg-mono: 'IBM Plex Mono', 'D2Coding', ui-monospace, monospace;

    /* 본문: 글자 크기와 행간 */
    --wg-text: calc(var(--mainFontSize) * 0.97);
    --wg-lh: calc(var(--wg-text) * 1.85);
    --wg-measure: clamp(14px, 6%, 44px);  /* 본문 좌우 여백 */

    /* 꾸밈 글자 */
    --wg-spine-char: 'MANUSCRIPT \00B7  原稿';
    --wg-spine-user: 'REPLY \00B7  答書';
    --wg-endmark: '\25C7';

    /* 머리 원고지 띠 */
    --wg-cell: 32px;              /* 칸 */
    --wg-gap: 8px;                /* 줄 사이 틈 */
    --wg-pad: 74px;               /* 구분선과 띠 사이 */
    --wg-after: 108px;            /* 본문 끝과 다음 구분선 사이 */
    --wg-side: 18px;
    --wg-photo: 128px;
    --wg-stamp-size: 36px;               /* 번호 도장 지름 */
    --wg-frame: 7px;
    --wg-chin: 28px;
    --wg-tilt: -4deg;

    /* 상단 메뉴 · 입력창 아이콘 */
    --topBarIconSize: calc(var(--mainFontSize) * 0.95);
    --topBarBlockPadding: 16px;
    --bottomFormIconSize: calc(var(--mainFontSize) * 1.35);

    --mainFontFamily: var(--wg-serif);
    --monoFontFamily: var(--wg-mono);
}

@media (max-width: 600px) {
    :root {
        --wg-cell: 25px;
        --wg-gap: 6px;
        --wg-pad: 62px;
        --wg-after: 92px;
        --wg-side: 10px;
        --wg-photo: 100px;
        --wg-stamp-size: 31px;
        --wg-frame: 5px;
        --wg-chin: 22px;
        --topBarIconSize: calc(var(--mainFontSize) * 1.05);
        --bottomFormIconSize: calc(var(--mainFontSize) * 1.5);
    }
}

/* ----------------------------------------------------------------------------
   책상과 종이
   ---------------------------------------------------------------------------- */

body {
    background-color: var(--wg-desk);
    font-family: var(--wg-serif);
    text-shadow: none;
}

#bg1 {
    background: var(--wg-desk) !important;
    opacity: 1 !important;
}

#chat {
    background-color: transparent;
    text-shadow: none;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    padding: 0 6px;
    scrollbar-color: rgba(28, 30, 33, 0.25) transparent;
}

::selection {
    background: rgba(109, 127, 145, 0.28);
    color: var(--wg-ink);
}

/* ----------------------------------------------------------------------------
   상단 메뉴 — 작은 아이콘, 책 머리말 같은 이중 괘선
   ---------------------------------------------------------------------------- */

#top-bar {
    background-color: var(--wg-paper);
    box-shadow: none;
    border-bottom: 1px solid var(--wg-print-faint);
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
}

#top-settings-holder {
    justify-content: center;
    align-items: center;
    gap: clamp(6px, 3.2vw, 34px);
}

#top-settings-holder > .drawer {
    flex: 0 0 auto;
    width: auto;
    height: 100%;
    align-items: center;
    justify-content: center;
}

#top-settings-holder .drawer-toggle {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
}

#top-settings-holder .drawer-icon {
    color: var(--wg-ink);
    font-size: var(--topBarIconSize);
    line-height: 1;
    padding: 4px;
}

#top-settings-holder .drawer-icon.closedIcon {
    opacity: 0.42;
}

#top-settings-holder .drawer-icon.closedIcon:hover,
#top-settings-holder .drawer-icon.openIcon {
    opacity: 1;
}

/* ----------------------------------------------------------------------------
   메시지 한 장
   .mesAvatarWrapper 를 풀어(display: contents) 아바타·번호·타이머를
   .mes 기준으로 배치합니다.
   ---------------------------------------------------------------------------- */

#chat .mes {
    --wg-pitch: calc(var(--wg-cell) + var(--wg-gap));
    --wg-pol-w: calc(var(--wg-photo) + var(--wg-frame) * 2);
    --wg-pol-h: calc(var(--wg-photo) + var(--wg-frame) + var(--wg-chin));
    --wg-band-near: calc(var(--wg-side) + var(--wg-pol-w) * 0.42);
    --wg-band-far: var(--wg-side);
    /* 칸 글꼴: 나눔명조, 글자 크기 = 칸의 75%. 한글 0.95em + 자간 = 한 칸 */
    --wg-cell-font: calc(var(--wg-cell) * 0.75);
    --wg-track: calc(var(--wg-cell) * 0.2875);
    --wg-cell-family: 'Nanum Myeongjo', 'Noto Serif KR', serif;
    --wg-band-bg: var(--wg-paper);
    /* 캐릭터 원고지는 먹색 선 */
    --wg-band-frame: var(--wg-ink);
    --wg-band-line: rgba(28, 30, 33, 0.62);

    /* 1행: 폴라로이드 + 원고지 띠 / 2행: 버튼 / 그 아래: 본문 */
    display: grid;
    grid-template-columns:
        calc(var(--wg-pol-w) * 0.42)
        calc(var(--wg-pol-w) * 0.58)
        minmax(0, 1fr);
    align-items: start;
    position: relative;
    padding: var(--wg-pad) var(--wg-side) var(--wg-after);
    margin: 0;
    /* 구분선 — 원고지 낱장의 머리처럼, 칸마다 눈금을 새긴 자 */
    border-top: 1px solid var(--wg-ink);
    background-color: transparent;
    background-image:
        linear-gradient(to right, var(--wg-print) 1px, transparent 1px),
        linear-gradient(to right, var(--wg-print-line) 1px, transparent 1px),
        linear-gradient(var(--wg-print-faint), var(--wg-print-faint));
    background-size: calc(var(--wg-cell) * 5) 9px, var(--wg-cell) 5px, 100% 1px;
    background-repeat: repeat-x, repeat-x, no-repeat;
    background-position:
        right var(--wg-side) top 0,
        right var(--wg-side) top 0,
        0 4px;
    color: var(--wg-ink-body);
    overflow: visible;
}

#chat .mes:first-child {
    margin-top: 14px;
}

#chat .mes.last_mes {
    margin-bottom: 0;
}

/* 폴라로이드 아래 글씨 — 아바타와 같은 상자를 같은 각도로 */
#chat .mes .avatar::after {
    content: var(--wg-caption-char);
    position: absolute;
    left: var(--wg-frame);
    right: var(--wg-frame);
    bottom: calc(var(--wg-chin) * 0.2);
    text-align: right;
    font-family: var(--wg-hanja);
    font-size: calc(var(--wg-chin) * 0.32);
    font-weight: 400;
    letter-spacing: 0.3em;
    line-height: 1.2;
    color: var(--wg-ink-soft);
    white-space: nowrap;
    overflow: hidden;
    pointer-events: none;
}

#chat .mes .mesAvatarWrapper,
#chat .mes .mes_block,
#chat .mes .ch_name,
#chat .mes .ch_name > .flex-container {
    display: contents;
}

#chat .mes .for_checkbox {
    position: absolute;
    width: 0;
    height: 0;
}

#chat .mes .mes_reasoning_details { grid-row: 3; grid-column: 1 / -1; }
#chat .mes .mes_text              { grid-row: 4; grid-column: 1 / -1; }
#chat .mes .mes_media_wrapper     { grid-row: 5; grid-column: 1 / -1; }
#chat .mes .mes_file_wrapper      { grid-row: 6; grid-column: 1 / -1; }
#chat .mes .mes_bias              { grid-row: 7; grid-column: 1 / -1; }

/* 폴라로이드 */
#chat .mes .avatar {
    /* 띠 높이와 상관없이 띠의 세로 가운데에. 위아래 음수 여백으로 행 높이에는 끼어들지 않습니다 */
    grid-row: 1;
    grid-column: 1 / 3;
    align-self: center;
    justify-self: start;
    position: relative;
    margin: calc(var(--wg-pol-h) / -2) 0;
    width: var(--wg-pol-w);
    height: var(--wg-pol-h);
    box-sizing: border-box;
    padding: var(--wg-frame) var(--wg-frame) var(--wg-chin);
    flex: none;
    background: #ffffff;
    border-radius: 1px;
    transform: rotate(var(--wg-tilt));
    box-shadow:
        0 0 0 1px rgba(28, 30, 33, 0.06),
        0 6px 14px -5px rgba(28, 30, 33, 0.30);
    z-index: 2;
    transition: transform var(--animation-duration-2x) ease;
}

#chat .mes .avatar:hover {
    transform: rotate(0deg) scale(1.03);
}

#chat .mes .avatar img {
    width: var(--wg-photo);
    height: var(--wg-photo);
    border-radius: 0;
    border: 0;
    box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.06);
    object-fit: cover;
    filter: var(--wg-photo-filter);
    transition: filter var(--animation-duration-2x) ease;
}

/* 띠 위 여백의 작은 인쇄 글씨: 생성 시간 */
#chat .mes .mes_timer {
    position: absolute;
    top: calc(var(--wg-pad) - 20px);
    height: 14px;
    line-height: 14px;
    margin: 0;
    padding: 0;
    font-family: var(--wg-mono);
    font-size: 10.5px;
    font-weight: 400;
    letter-spacing: 0.04em;
    color: var(--wg-ink-faint);
    opacity: 1;
    white-space: nowrap;
    z-index: 1;
}

/* 날짜 — 이름 위 줄 */
#chat .mes .timestamp {
    order: -1;
    /* 날짜는 칸에 맞추지 않고 명조로 촘촘하게 */
    font-family: var(--wg-title) !important;
    font-size: calc(var(--wg-cell) * 0.5) !important;
    font-weight: 700;
    letter-spacing: 0.04em !important;
    word-spacing: 0.1em;
    color: var(--wg-ink-body);
    padding-right: calc(var(--wg-cell) * 0.15) !important;
}

#chat .mes .mes_timer {
    right: calc(var(--wg-band-far) + var(--wg-stamp-size) + 8px);
}

/* 원고지 머리 여백에 인쇄된 표기 */
#chat .mes .tokenCounterDisplay,
#chat .mes .ch_name::after {
    position: absolute;
    top: calc(var(--wg-pad) - 20px);
    left: calc(var(--wg-side) + var(--wg-pol-w) + 8px);
    height: 14px;
    margin: 0;
    padding: 0;
    line-height: 14px;
    font-family: var(--wg-mono);
    font-size: 10px;
    letter-spacing: 0.12em;
    color: var(--wg-print);
    opacity: 1;
    white-space: nowrap;
    z-index: 1;
}

/* 토큰 수 표시를 켜면: 原稿用紙 · 412t */
#chat .mes .tokenCounterDisplay::before {
    content: var(--wg-paper-label) '\00A0\00B7\00A0';
    font-family: var(--wg-title);
    font-weight: 700;
    letter-spacing: 0.22em;
}

#chat .mes .tokenCounterDisplay:empty::before {
    content: var(--wg-paper-label);
}

/* 토큰 수 표시를 끄면 이름만 */
#chat .mes .ch_name::after {
    content: none;
    font-family: var(--wg-title);
    font-weight: 700;
    letter-spacing: 0.22em;
}

body.no-tokenCount #chat .mes .ch_name::after {
    content: var(--wg-paper-label);
}

/* 번호 — 띠 모서리에 찍은 원형 도장 */
#chat .mes .mesIDDisplay {
    position: absolute;
    top: calc(var(--wg-pad) - var(--wg-stamp-size) * 0.55);
    right: calc(var(--wg-band-far) - 6px);
    width: var(--wg-stamp-size);
    height: var(--wg-stamp-size);
    box-sizing: border-box;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0;
    padding: 0;
    border: 1px solid var(--wg-print);
    border-radius: 50%;
    box-shadow: inset 0 0 0 2px var(--wg-paper), inset 0 0 0 2.6px var(--wg-print-line);
    background: var(--wg-paper);
    font-family: var(--wg-mono);
    font-size: 11px;
    font-weight: 500;
    letter-spacing: 0;
    line-height: 1;
    color: var(--wg-print);
    opacity: 1;
    transform: rotate(-8deg);
    white-space: nowrap;
    z-index: 2;
}

/* 원고지 띠 — 날짜와 이름을 담은 상자 자체에 칸을 그립니다.
   글이 길면 줄이 늘고, 띠도 함께 늘어납니다.
   한글은 한 칸에 한 자, 띄어쓰기도 한 칸 */
#chat .mes .mes_block,
#chat .mes .ch_name,
#chat .mes .ch_name > .flex-container {
    position: static;
}

#chat .mes .ch_name > .flex-container > .flex-container {
    --wg-k: 1;                    /* 끝에서 비워 둘 칸 */
    grid-row: 1;
    grid-column: 2 / 4;
    position: relative;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0;
    width: auto;
    margin: 0 0 16px;
    /* 폴라로이드 쪽은 가리지 않도록 비우고, 끝은 칸 경계에 맞춥니다 */
    padding:
        calc(var(--wg-gap) / 2)
        calc(var(--wg-cell) * var(--wg-k) - var(--wg-track) / 2 - 1px)
        calc(var(--wg-gap) / 2)
        calc(var(--wg-pol-w) - var(--wg-pol-w) * 0.42 + 8px);
    border: 1px solid var(--wg-band-frame);
    outline: 1px solid var(--wg-band-frame);
    outline-offset: 2px;
    background-color: var(--wg-band-bg);
    background-image:
        linear-gradient(to bottom,
            transparent var(--wg-gap),
            var(--wg-band-line) var(--wg-gap), var(--wg-band-line) calc(var(--wg-gap) + 1px),
            transparent calc(var(--wg-gap) + 1px), transparent calc(var(--wg-pitch) - 1px),
            var(--wg-band-line) calc(var(--wg-pitch) - 1px)),
        linear-gradient(to bottom, var(--wg-band-bg) var(--wg-gap), transparent var(--wg-gap)),
        linear-gradient(to right, var(--wg-band-line) 1px, transparent 1px);
    background-size: 100% var(--wg-pitch), 100% var(--wg-pitch), var(--wg-cell) 100%;
    background-position: 0 0, 0 0, right -1px top 0;
    background-repeat: repeat;
    font-family: var(--wg-cell-family);
    font-size: var(--wg-cell-font);
    line-height: var(--wg-pitch);
    letter-spacing: var(--wg-track);
    text-align: right;
}

#chat .mes .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes .ch_name > .flex-container > .flex-container > .timestamp {
    display: block;
    align-self: stretch;
    width: 100%;
    max-width: 100%;
    margin: 0;
    padding: 0;
    font-family: inherit;
    font-size: inherit;
    line-height: inherit;
    letter-spacing: inherit;
    text-align: inherit;
    white-space: normal;
    word-break: keep-all;
    overflow-wrap: anywhere;
    opacity: 1;
}

#chat .mes .name_text {
    position: relative;
    /* 명조 한글의 먹 중심이 줄 가운데보다 0.055em 위에 있어 그만큼 내립니다 */
    top: 0.055em;
    font-weight: 700;
    /* 띄어쓰기도 한 칸 */
    word-spacing: calc(var(--wg-cell) - var(--wg-cell-font) * 0.27 - var(--wg-track));
    color: var(--wg-ink);
}

/* 영문 이름 — 영문 글자로 시작하는 이름은 칸 자간을 풀고 촘촘하게 적습니다.
   (CSS로는 글자마다 자간을 다르게 줄 수 없어, 이름의 첫 글자로 구분합니다) */
#chat .mes[ch_name^="a" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="b" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="c" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="d" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="e" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="f" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="g" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="h" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="i" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="j" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="k" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="l" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="m" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="n" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="o" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="p" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="q" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="r" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="s" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="t" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="u" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="v" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="w" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="x" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="y" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="z" i] .ch_name > .flex-container > .flex-container > .name_text {
    letter-spacing: 0.03em;
    word-spacing: 0.2em;
}

#chat .mes .mes_ghost {
    position: absolute;
    top: 2px;
    left: calc(var(--wg-pol-w) * 0.58 + 6px);
    font-size: 11px;
    line-height: 1;
    letter-spacing: 0;
    color: var(--wg-ink-faint);
}

#chat .mes .mes_block {
    padding: 0;
    width: 100%;
    overflow: visible;
}

/* 메시지 버튼 — 띠와 본문 사이, 양옆으로 가는 괘선을 그은 구분 줄 */
#chat .mes .mes_buttons,
#chat .mes .mes_edit_buttons {
    justify-content: center;
    align-items: center;
    align-self: stretch;
    float: none;
    gap: 2px;
    grid-row: 2;
    grid-column: 1 / -1;
    /* 가운데 정렬. 두 줄짜리 띠 아래로 늘어진 폴라로이드보다 더 아래에 둡니다 */
    margin: max(6px, calc((var(--wg-pol-h) - var(--wg-pitch) * 2 - var(--wg-gap)) / 2 - 2px)) var(--wg-measure) 22px;
    min-height: 36px;
    overflow: visible;
}

#chat .mes .mes_buttons::before,
#chat .mes .mes_buttons::after,
#chat .mes .mes_edit_buttons::before,
#chat .mes .mes_edit_buttons::after {
    content: '';
    flex: 1 1 0;
    min-width: 12px;
    height: 5px;
    margin: 0 10px;
    border-top: 1px solid var(--wg-print-line);
    border-bottom: 1px solid var(--wg-print-faint);
}

#chat .mes .mes_button,
#chat .mes .extraMesButtons > div {
    color: var(--wg-ink);
    filter: none;
    opacity: 0.35;
    padding: 4px 7px;
    font-size: 13px;
}

#chat .mes .mes_button:hover,
#chat .mes .extraMesButtons > div:hover {
    opacity: 1;
}

#chat .mes .mes_edit_buttons .menu_button {
    background: var(--wg-paper);
    border: 1px solid rgba(28, 30, 33, 0.22);
    border-radius: 999px;
    color: var(--wg-ink);
    width: 30px;
    height: 30px;
    font-size: 12px;
    opacity: 0.8;
    filter: none;
}

#chat .mes .mes_edit_buttons .menu_button:hover {
    opacity: 1;
    border-color: var(--wg-ink);
}

/* ----------------------------------------------------------------------------
   본문 — 원고지 한 장에 쓴 글
   줄마다 칸 줄(행)과 그 사이의 틈이 번갈아 지나갑니다.
   ---------------------------------------------------------------------------- */

#chat .mes .mes_text {
    position: relative;
    margin: 0;
    padding: 2px var(--wg-measure) 0;
    background: none;
    border: 0;
    box-shadow: none;
    font-family: var(--wg-serif);
    font-size: var(--wg-text);
    font-weight: 400;
    line-height: var(--wg-lh);
    color: var(--wg-ink-body);
    letter-spacing: 0.01em;
    word-break: keep-all;
    overflow-wrap: anywhere;
    overflow-x: auto;
    text-shadow: none;
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
}

#chat .mes .mes_text:empty {
    display: none;
}

#chat .mes .mes_text p {
    margin: 0 0 0.95em;
}

#chat .mes .mes_text > :last-child {
    margin-bottom: 0;
}

/* 글 끝 표시 — 잡지 기사의 마침 기호처럼 */
#chat .mes .mes_text > p:last-child::after {
    content: var(--wg-endmark);
    display: inline-block;
    margin-left: 0.6em;
    font-size: 0.62em;
    line-height: 1;
    vertical-align: 0.2em;
    color: var(--wg-print);
}

#chat .mes .mes_text br {
    margin: 0;
}

#chat .mes .mes_text q {
    color: var(--wg-quote);
}

#chat .mes .mes_text em,
#chat .mes .mes_text i {
    color: var(--wg-em);
    font-style: normal;
}

#chat .mes .mes_text q em,
#chat .mes .mes_text q i {
    color: inherit;
}

#chat .mes .mes_text strong {
    font-weight: 700;
    color: var(--wg-ink);
}

#chat .mes .mes_text u {
    color: inherit;
    text-decoration-color: var(--wg-print);
    text-decoration-thickness: 1px;
    text-underline-offset: 5px;
}

/* 장면 전환 */
#chat .mes .mes_text hr {
    border: 0;
    height: var(--wg-lh);
    margin: 0.4em 0 0.9em;
    opacity: 1;
    background: none;
}

#chat .mes .mes_text hr::after {
    content: '＊';
    display: block;
    text-align: center;
    line-height: var(--wg-lh);
    font-size: 0.9em;
    color: var(--wg-ink-soft);
}

/* 인용 — 책 뒤표지의 제사(題辭)처럼 */
#chat .mes .mes_text blockquote {
    margin: 0.4em clamp(0px, 4%, 24px) 1.2em;
    padding: 0.9em 1.4em;
    background: var(--wg-wash);
    border: 0;
    border-radius: 2px;
    color: var(--wg-ink);
    text-align: center;
    font-family: var(--wg-title);
    line-height: 1.9;
}

#chat .mes .mes_text blockquote::before {
    content: '\201C';
    display: block;
    height: 0.55em;
    font-family: var(--wg-title);
    font-size: 2.2em;
    line-height: 1;
    color: var(--wg-print);
}

#chat .mes .mes_text blockquote p {
    margin: 0;
}

/* 장 제목 */
#chat .mes .mes_text h1,
#chat .mes .mes_text h2,
#chat .mes .mes_text h3,
#chat .mes .mes_text h4 {
    font-family: var(--wg-title);
    font-weight: 700;
    line-height: var(--wg-lh);
    margin: 0.4em 0 0.8em;
    font-size: 1.05em;
    text-align: center;
    letter-spacing: 0.2em;
    color: var(--wg-ink);
}

#chat .mes .mes_text h1 {
    font-size: 1.2em;
}

#chat .mes .mes_text ul,
#chat .mes .mes_text ol {
    margin: 0;
    padding-left: 2em;
}

#chat .mes .mes_text code {
    font-family: var(--wg-mono);
    font-size: 0.86em;
    background: var(--wg-wash);
    border: 0;
    border-radius: 3px;
    padding: 0.1em 0.35em;
    color: var(--wg-ink);
}

#chat .mes .mes_text pre {
    margin: calc(var(--wg-lh) * 0.25) 0;
    line-height: 1.6;
}

#chat .mes .mes_text pre code {
    display: block;
    padding: 12px 14px;
    background: #f1f3f5;
    border: 1px solid var(--wg-print-faint);
    border-radius: 6px;
    text-shadow: none;
}

#chat .mes .mes_text img {
    border-radius: 2px;
    max-width: 100%;
}

#chat .mes .mes_text table {
    border-collapse: collapse;
    background: var(--wg-paper);
    line-height: 1.7;
}

#chat .mes .mes_text th,
#chat .mes .mes_text td {
    border: 1px solid var(--wg-print-line);
    padding: 3px 10px;
}

#chat .mes .mes_text a {
    color: var(--wg-ink);
    text-decoration-color: var(--wg-print);
    text-underline-offset: 4px;
}

/* 편집 중 — 카드는 비우고 입력창이 원고가 됩니다 */
#chat .mes .mes_text:has(.edit_textarea) {
    padding: 0;
}

#chat .mes .edit_textarea {
    margin: 0;
    padding: 12px var(--wg-measure);
    background: var(--wg-paper);
    border: 1px solid var(--wg-ink);
    border-radius: 12px;
    box-shadow: 0 0 0 3px var(--wg-paper), 0 0 0 4px var(--wg-print-line);
    font-family: var(--wg-serif);
    font-size: var(--wg-text);
    line-height: 1.9;
    color: var(--wg-ink);
}

/* 생각(추론) 블록 — 원고 위에 끼운 쪽지 */
#chat .mes .mes_reasoning_details {
    margin: 0 0 12px;
    padding: 6px 14px;
    background: var(--wg-wash);
    border: 1px dashed var(--wg-print);
    border-radius: 8px;
}

#chat .mes .mes_reasoning_summary {
    font-family: var(--wg-mono);
    font-size: 12px;
    color: var(--wg-ink-soft);
}

#chat .mes .mes_reasoning {
    font-family: var(--wg-serif);
    font-size: calc(var(--wg-text) * 0.93);
    line-height: 1.8;
    color: var(--wg-ink-soft);
    padding: 6px 0 4px;
}

/* 스와이프 */
#chat .mes .swipe_left,
#chat .mes .swipe_right {
    color: var(--wg-ink);
    font-size: 14px;
    opacity: 0.4;
    filter: none;
}

#chat .mes .swipe_left:hover,
#chat .mes .swipe_right:hover {
    opacity: 1;
}

#chat .mes .swipe_left {
    left: var(--wg-side);
    bottom: 10px;
}

#chat .mes .swipeRightBlock {
    right: var(--wg-side);
    bottom: 10px;
    flex-direction: row-reverse;
    align-items: center;
    gap: 4px;
}

#chat .mes .swipes-counter {
    font-family: var(--wg-mono);
    font-size: 11px;
    letter-spacing: 0.08em;
    color: var(--wg-ink-soft);
    margin: 0;
    min-width: 0;
    height: auto;
}

/* 책등 — 본문 옆에 세로로 인쇄된 표기 */
#chat .mes .mes_text::before {
    content: var(--wg-spine-char);
    position: absolute;
    top: 6px;
    bottom: 4px;
    left: 0;
    width: 14px;
    box-sizing: border-box;
    border-right: 1px solid var(--wg-print-faint);
    writing-mode: vertical-rl;
    font-family: var(--wg-mono);
    font-size: 8.5px;
    letter-spacing: 0.32em;
    line-height: 14px;
    color: var(--wg-print);
    white-space: nowrap;
    overflow: hidden;
    pointer-events: none;
}

#chat .mes[is_user="true"] .mes_text::before {
    content: var(--wg-spine-user);
    left: auto;
    right: 0;
    border-right: 0;
    border-left: 1px solid var(--wg-print-faint);
}

#chat .mes .mes_text:has(.edit_textarea)::before {
    display: none;
}

@media (max-width: 600px) {
    #chat .mes .mes_text::before {
        width: 12px;
        line-height: 12px;
        font-size: 7.5px;
        letter-spacing: 0.26em;
    }

    #chat .mes .mes_text {
        padding-left: 26px;
        padding-right: 8px;
    }

    #chat .mes[is_user="true"] .mes_text {
        padding-left: 8px;
        padding-right: 26px;
    }
}

/* ----------------------------------------------------------------------------
   유저 메시지 — 좌우를 뒤집어 맞은편 페이지처럼
   ---------------------------------------------------------------------------- */

#chat .mes[is_user="true"] {
    --wg-tilt: 4deg;
    --wg-band-bg: var(--wg-paper-user);
    --wg-band-frame: var(--wg-print);
    --wg-band-line: var(--wg-print-line);
    background-position:
        left var(--wg-side) top 0,
        left var(--wg-side) top 0,
        0 4px;
}

#chat .mes[is_user="true"] {
    grid-template-columns:
        minmax(0, 1fr)
        calc(var(--wg-pol-w) * 0.58)
        calc(var(--wg-pol-w) * 0.42);
}

#chat .mes[is_user="true"] .avatar {
    grid-column: 2 / 4;
    justify-self: end;
}

#chat .mes[is_user="true"] .avatar::after {
    content: var(--wg-caption-user);
    text-align: left;
}

#chat .mes[is_user="true"] .ch_name > .flex-container > .flex-container {
    align-items: flex-start;
    grid-column: 1 / 3;
    margin: 0 0 16px;
    padding:
        calc(var(--wg-gap) / 2)
        calc(var(--wg-pol-w) - var(--wg-pol-w) * 0.42 + 8px)
        calc(var(--wg-gap) / 2)
        calc(var(--wg-cell) * var(--wg-k) + var(--wg-track) / 2);
    background-position: 0 0, 0 0, left 0 top 0;
    text-align: left;
}

#chat .mes[is_user="true"] .mes_timer {
    right: auto;
    left: calc(var(--wg-band-far) + var(--wg-stamp-size) + 8px);
}

#chat .mes[is_user="true"] .tokenCounterDisplay,
#chat .mes[is_user="true"] .ch_name::after {
    left: auto;
    right: calc(var(--wg-side) + var(--wg-pol-w) + 8px);
}

#chat .mes[is_user="true"] .mesIDDisplay {
    right: auto;
    left: calc(var(--wg-band-far) - 6px);
    transform: rotate(8deg);
}



#chat .mes[is_user="true"] .mes_ghost {
    left: auto;
    right: calc(var(--wg-pol-w) * 0.58 + 6px);
}

/* 시스템 메시지 */
#chat .mes[is_system="true"] .mes_text {
    color: var(--wg-ink-soft);
}

/* 아바타 숨김 설정 — 띠만 남깁니다 */
body.hideChatAvatars #chat .mes {
    --wg-band-near: var(--wg-side);
    --wg-pol-w: 0px;
}

/* 선택(삭제 모드) */
#chat .mes.selected {
    background-color: rgba(28, 30, 33, 0.06);
}

#chat .mes .del_checkbox {
    position: absolute;
    top: 8px;
    left: 8px;
    z-index: 5;
}

/* 컨텍스트 경계 */
#chat .mes.lastInContext {
    border-top: 1px dashed var(--wg-print) !important;
}

/* ----------------------------------------------------------------------------
   하단 입력창 — 원고지 한 줄
   ---------------------------------------------------------------------------- */

#form_sheld {
    margin-top: 0;
}

#send_form {
    background-color: var(--wg-paper);
    border: 0;
    border-top: 1px solid var(--wg-print-faint);
    border-radius: 0;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    padding: 4px 4px 6px;
}

#send_form:has(#send_textarea:focus-visible) {
    outline: none;
    border-color: var(--wg-print-line);
}

@media screen and (max-width: 1000px) {
    #leftSendForm,
    #rightSendForm {
        width: auto;
        flex-wrap: nowrap;
        height: auto;
    }
}

#send_textarea {
    font-family: var(--wg-serif);
    font-size: var(--wg-text);
    line-height: 1.75;
    color: var(--wg-ink);
    text-shadow: none;
    padding: 8px 10px;
    background-image: linear-gradient(transparent calc(100% - 1px), var(--wg-print-line) calc(100% - 1px));
    --progColor: var(--wg-print);
}

#send_textarea::placeholder {
    color: var(--wg-ink-faint);
    font-style: normal;
}

#leftSendForm > div,
#rightSendForm > div:not(.mes_stop),
#send_form .mes_stop {
    color: var(--wg-ink);
    opacity: 0.5;
}

#leftSendForm > div:hover,
#rightSendForm > div:hover {
    opacity: 1;
    filter: none;
}

/* ----------------------------------------------------------------------------
   패널 · 팝업 — 같은 종이 위에서
   ---------------------------------------------------------------------------- */

.drawer-content,
#left-nav-panel,
#right-nav-panel,
.popup,
#character_popup,
#WorldInfo,
.options-content,
.list-group,
#extensionsMenu {
    background-color: var(--wg-paper);
    color: var(--wg-ink);
    text-shadow: none;
    border-color: rgba(28, 30, 33, 0.16);
    box-shadow: 0 10px 30px -14px rgba(28, 30, 33, 0.4);
}

.menu_button,
.menu_button_icon,
.right_menu_button {
    color: var(--wg-ink);
}

.menu_button {
    background-color: rgba(28, 30, 33, 0.04);
    border: 1px solid rgba(28, 30, 33, 0.16);
    filter: none;
}

.menu_button:hover {
    background-color: var(--wg-wash);
}

.text_pole,
textarea,
select,
input[type="text"],
input[type="number"],
input[type="search"] {
    background-color: #ffffff;
    color: var(--wg-ink);
    border: 1px solid rgba(28, 30, 33, 0.18);
    text-shadow: none;
}

#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    background-image: none;
    background-color: var(--wg-wash);
    border: 0;
    border-bottom: 1px solid var(--wg-print);
    border-radius: 3px 3px 0 0;
    color: var(--wg-ink);
}

#extensions_settings .inline-drawer-toggle.inline-drawer-header:hover,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header:hover,
.standoutHeader.inline-drawer-header:hover {
    filter: none;
    background-color: #d8dfe6;
}

.standoutHeader ~ .inline-drawer-content {
    background-color: rgba(255, 255, 255, 0.6);
}

#extensionsMenu > .extension_container > div,
#extensionsMenu > div:not(.extension_container),
.options-content a,
.list-group-item {
    opacity: 0.8;
}

.list-group-item:hover,
.options-content a:hover {
    background-color: var(--wg-wash);
}

h1, h2, h3, h4, h5,
.standoutHeader {
    font-family: var(--wg-title);
    letter-spacing: 0.01em;
}

#toast-container > div {
    background-color: var(--wg-paper);
    color: var(--wg-ink);
    border: 1px solid rgba(28, 30, 33, 0.18);
    box-shadow: 0 8px 20px -10px rgba(28, 30, 33, 0.4);
    opacity: 1;
}

#toast-container > .toast-success { border-left: 4px solid var(--wg-print) !important; }
#toast-container > .toast-info { border-left: 4px solid var(--wg-print-line) !important; }
#toast-container > .toast-warning { border-left: 4px solid var(--wg-ink-soft) !important; }
#toast-container > .toast-error { border-left: 4px solid var(--wg-ink) !important; }

/* ----------------------------------------------------------------------------
   스크롤바
   ---------------------------------------------------------------------------- */

::-webkit-scrollbar-thumb {
    background-color: rgba(28, 30, 33, 0.22);
    border-radius: 8px;
}

::-webkit-scrollbar-track {
    background: transparent;
}

/* ----------------------------------------------------------------------------
   움직임 줄이기
   ---------------------------------------------------------------------------- */

@media (prefers-reduced-motion: reduce) {
    #chat .mes .avatar,
    #chat .mes .avatar:hover {
        transition: none;
        transform: rotate(var(--wg-tilt));
    }
}

/* 아바타를 숨기면 구분 줄도 폴라로이드 자리를 비우지 않습니다 */
body.hideChatAvatars #chat .mes .mes_buttons,
body.hideChatAvatars #chat .mes .mes_edit_buttons {
    margin-top: 6px;
}
